namespace Challenge;public sealed class InboxStore{public HashSet<string> Processed=new();public List<string> Invoices=new();internal object Gate=new();}public sealed class Consumer(InboxStore store){public bool Handle(string id,bool fail=false){lock(store.Gate){if(store.Processed.Contains(id))return true;store.Invoices.Add(id);try{if(fail)throw new InvalidOperationException();store.Processed.Add(id);return true;}catch{store.Invoices.Remove(id);throw;}}}}
